          O.High(c, a + b, d);
          O.High(c, a, b + d);
        }
      } else {
        O.High(c, b, d);
        O.High(c, a + b, d);
        O.High(c, a, c);
      }
    } else {
      O.High(c, a, b);
      if b + d <= c {
        O.Low(c, b, d);
        O.High(c, c, d);
        O.High(c, a, b + d);
      } else {
        O.High(c, b, d);
        O.High(c, c, d);
        O.High(c, a, c);
      }
